<?php
declare(strict_types=1);
require __DIR__ . '/app/bootstrap.php';
require_admin();
$flash = take_flash();
$imports = [];
try { $imports = db()->query('SELECT snapshot_date, original_name, file_size, created_at FROM imports ORDER BY snapshot_date DESC, id DESC LIMIT 20')->fetchAll(); } catch (Throwable $e) { $flash = ['type' => 'error', 'message' => 'Database unavailable. Check config.php and import sql/schema.sql.']; }
?><!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Upload center · PartPulse</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700;800&family=Roboto+Mono:wght@500;600&display=swap" rel="stylesheet"><link rel="stylesheet" href="assets/style.css"></head><body><a class="skip-link" href="#main">Skip to content</a><header class="topbar"><a class="brand brand-dark" href="index.php"><svg viewBox="0 0 36 36" aria-hidden="true"><path d="M4 20h6l3-8 5 15 4-11 3 4h7"/><circle cx="29" cy="20" r="3"/></svg><span>PartPulse</span></a><nav class="top-actions" aria-label="Admin navigation"><a class="button ghost" href="index.php">Public view</a><a class="button ghost" href="logout.php">Sign out</a></nav></header><main id="main" class="admin-shell"><section class="admin-intro"><p class="eyebrow">Administrator</p><h1>Upload center</h1><p>One task each morning: choose the dated PartPulse XLSX and upload it. The source workbook stays stored on the server.</p></section><?php if ($flash): ?><p class="alert <?= e($flash['type']) ?>" role="status"><?= e($flash['message']) ?></p><?php endif; ?><section class="upload-panel"><form action="upload.php" method="post" enctype="multipart/form-data" class="upload-form" id="uploadForm"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><label class="dropzone" for="workbook"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 16V4m0 0L7 9m5-5 5 5M5 14v5h14v-5"/></svg><strong>Choose the daily workbook</strong><span id="fileName">.xlsx only · maximum <?= (int)($config['max_upload_bytes']/1024/1024) ?> MB</span><input id="workbook" name="workbook" type="file" accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" required></label><button class="button primary" id="uploadButton" type="submit">Import and publish</button></form></section><section class="history"><div class="section-head"><div><p class="eyebrow">Archive</p><h2>Recent uploads</h2></div><span class="muted"><?= count($imports) ?> shown</span></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Original file</th><th>Size</th><th>Uploaded</th></tr></thead><tbody><?php foreach ($imports as $row): ?><tr><td><?= e($row['snapshot_date']) ?></td><td><?= e($row['original_name']) ?></td><td><?= number_format((int)$row['file_size']/1024, 1) ?> KB</td><td><?= e($row['created_at']) ?></td></tr><?php endforeach; ?><?php if (!$imports): ?><tr><td colspan="4">No workbooks uploaded yet.</td></tr><?php endif; ?></tbody></table></div></section></main><script>const f=document.querySelector('#workbook'),n=document.querySelector('#fileName'),b=document.querySelector('#uploadButton');f.addEventListener('change',()=>n.textContent=f.files[0]?.name||'.xlsx only');document.querySelector('#uploadForm').addEventListener('submit',()=>{b.disabled=true;b.textContent='Importing…'});</script></body></html>
